"""Self-consistency validation on large instances (no brute force)."""
import sys, random, time, json
sys.path.insert(0,'/workspace/scratch'); sys.path.insert(0,'/workspace/submission')
import gen_big, analyze as A
from fractions import Fraction
from math import lcm


def validate(req, res):
    inst = A._parse_request(req)
    edges = inst['edges']; coms = inst['commodities']; snaps = inst['snapshots']
    S=len(snaps); C=len(coms); E=len(edges)
    probs = []
    if res['status'] == 'infeasible':
        return probs
    k = res['min_faults']
    L = 1
    for c in coms:
        L = lcm(L, sum(w for _p, w in c[3]))
    def witness_ok(w, tag):
        if len(w['demands']) != S or len(w['links']) != S:
            probs.append((tag, 'shape')); return
        faulty = set()
        for s in range(S):
            qrow = w['demands'][s]
            if len(qrow) != C:
                probs.append((tag, 'commodity count')); return
            for c in range(C):
                lo, hi = snaps[s][1][c]
                if not (type(qrow[c]) is int and lo <= qrow[c] <= hi):
                    probs.append((tag, 'bound')); return
            ld = [0]*E; ing = {}; egr = {}
            for ci, c in enumerate(coms):
                ws = sum(wt for _p, wt in c[3])
                for p, wt in c[3]:
                    for ei in p:
                        ld[ei] += qrow[ci]*wt*(L//ws)
                ing[c[1]] = ing.get(c[1], 0) + qrow[ci]
                egr[c[2]] = egr.get(c[2], 0) + qrow[ci]
            got = ['%d/%d' % (Fraction(x, L).numerator, Fraction(x, L).denominator) for x in ld]
            if w['links'][s] != got:
                probs.append((tag, 'links mismatch'))
            if any(Fraction(ld[e], L) > edges[e][3] for e in range(E)):
                probs.append((tag, 'capacity'))
            metrics = {}
            for ci, c in enumerate(coms):
                metrics[('demand', c[0])] = qrow[ci]
            for ei, e in enumerate(edges):
                metrics[('link', e[0])] = Fraction(ld[ei], L)
            for n in inst['nodes']:
                metrics[('ingress', n)] = ing.get(n, 0)
                metrics[('egress', n)] = egr.get(n, 0)
            for (_o, m, t, lo, hi, dom) in snaps[s][4]:
                v = metrics[(m, t)]
                if not (lo <= v <= hi):
                    if dom is None:
                        probs.append((tag, 'trusted violated')); return
                    faulty.add(dom)
        if set(w['faults']) != faulty or len(faulty) != k:
            probs.append((tag, 'fault set %s vs k=%d' % (sorted(faulty), k)))
        for s in range(S):
            for c in range(C):
                lo, hi = res['snapshots'][s]['demands'][c]
                if not (lo <= w['demands'][s][c] <= hi):
                    probs.append((tag, 'witness outside range'))
                if lo > hi:
                    probs.append((tag, 'range inverted'))
            for e in range(E):
                lo, hi = res['snapshots'][s]['links'][e]
                fl = w['links'][s][e]
                a = Fraction(lo); b = Fraction(hi); f = Fraction(fl)
                if not (a <= f <= b):
                    probs.append((tag, 'witness link outside range'))
    witness_ok(res['witness'], 'witness')
    if res['status'] == 'ambiguous':
        if res['alternative'] is None:
            probs.append(('alternative', 'missing'))
        else:
            witness_ok(res['alternative'], 'alternative')
            if res['alternative']['demands'] == res['witness']['demands']:
                probs.append(('alternative', 'same'))
    else:
        if res['alternative'] is not None:
            probs.append(('alternative', 'should be null'))
        # unique: all ranges must be single points
        for s in range(S):
            for c in range(C):
                lo, hi = res['snapshots'][s]['demands'][c]
                if lo != hi:
                    probs.append(('unique', 'range not point'))
    # verdicts consistent with the witness
    for s in range(S):
        ctrl = snaps[s][2]; tol = snaps[s][3]
        agree = all(abs(res['witness']['demands'][s][c] - ctrl[c]) <= tol for c in range(C))
        v = res['snapshots'][s]['verdict']
        if v == 'consistent' and not agree:
            probs.append(('verdict', 'witness disagrees but consistent'))
        if v == 'inconsistent' and agree:
            probs.append(('verdict', 'witness agrees but inconsistent'))
    # faults
    if set(res['faults']['forced']) - set(res['faults']['possible']):
        probs.append(('faults', 'forced not subset of possible'))
    return probs


if __name__ == '__main__':
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 10
    fails = 0
    for i in range(n):
        rng = random.Random(1000 + i)
        tight = (i % 3 == 1)
        corr = [0.0, 0.05, 0.15, 0.3][i % 4]
        req = gen_big.build(rng, tight=tight, corrupt=corr, nsnap=1 + i % 4,
                            obs_per_snap=[8, 24, 64, 96][i % 4])
        inst = A._parse_request(req)
        t0 = time.time()
        res = A.analyze(inst, req['id'])
        dt = time.time() - t0
        probs = validate(req, res)
        print('%2d tight=%s corr=%.2f nsnap=%d obs=%3d k=%-3s %.2fs %s %s' % (
            i, tight, corr, 1 + i % 4, sum(len(s[4]) for s in inst['snapshots']),
            res.get('min_faults'), dt, res.get('status'),
            'OK' if not probs else 'PROBLEMS %s' % (probs,)), flush=True)
        if probs:
            fails += 1
    print('fails', fails)
PYEOF
